/**
 * @brief gpu_demo_mask_normal 对照
 *
 * @param head
 */
/* ------------------------------------------------------------------------------------*/
static void gpu_demo_mask_normal(pJLGPUTaskHead_t head)
{
    jlgpu_task_basic_param_init(GPU_TASK_FILL, 0x1, 0);
    task_param.task_type = GPU_TASK_CUSTOM | GPU_FILL_MASK;
    task_param.alpha = 0xff;
    task_param.blue = 0;
    task_param.red = 0xff;
    task_param.green = 0;
    task_param.image.width = 50;
    task_param.image.height = 50;
    task_param.mask_en = 1;
    task_param.draw.left = 100;
    task_param.draw.top = 100;
    task_param.draw.width = task_param.image.width;
    task_param.draw.height = task_param.image.height;
    jlgpu_get_win_rect(&task_param.area);
    task_param.fill.mask.big_end = 1;
    task_param.fill.mask.mask_inv = 0;
    task_param.fill.mask.mask_stride = 50;
    task_param.fill.mask.mask_format =  GPU_MASK_FORMAT_A4;
    task_param.fill.mask.mask_data =  test_image_a4;
    memcpy(&task_param.fill.mask.rect, &task_param.draw, sizeof(struct rect));

    jlgpu_update_task_by_id(head, task_param.task_id, task_param.element_id, &task_param);

}
